#include "Mcu.h"
#include "SysTimer.h"
#include "ETS.h"
#include "BswM_Interface.h"
#include "EcuM_Interface.h"

volatile uint32_t gvu32_cCycleCounter = 0u;

int main(void)
{
	STARTUP1();
	/* Loop forever */
	for(;;){
		switch(genu_vMCUState)
		{
		case MCU_STATE_STARTUP2:
			STARTUP2();
			Test_ETS_InitTask();
			break;

		case MCU_STATE_RUN:
			RUN();
			ETS_Task();
			break;

		case MCU_STATE_SHUTDOWN1:
			SHUTDOWN1();
			break;

		default:
			break;
		}

		if(genu_vMCUState == MCU_STATE_SHUTDOWN2)
		{
			break;
		}
		else
		{
			SysTimer_waitElapse();
			gvu32_cCycleCounter++;
		}
	}
	SHUTDOWN2();
}
